#include <algorithm>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std; using G=vector<unsigned>; using P=vector<int>; using ll=long long;
void need(bool b,const char*s){if(!b)throw runtime_error(s);} bool arc(const G&a,int i,int j){return a[i]>>j&1;} int pop(unsigned v){return __builtin_popcount(v);}
vector<P> maps(const G&a,bool anti){int n=a.size();P p(n,-1),used(n);vector<P> ans;function<void(int)> go=[&](int d){if(d==n){ans.push_back(p);return;}int u=-1;P best;for(int i=0;i<n;i++)if(p[i]<0){P options;for(int j=0;j<n;j++)if(!used[j]&&(anti?pop(a[i])+pop(a[j])==n-1:pop(a[i])==pop(a[j]))){bool yes=true;for(int k=0;k<n;k++)if(p[k]>=0&&arc(a,i,k)!=(arc(a,j,p[k])^anti)){yes=false;break;}if(yes)options.push_back(j);}if(options.empty())return;if(u<0||options.size()<best.size()){u=i;best=options;}}for(int j:best){p[u]=j;used[j]=1;go(d+1);used[j]=0;p[u]=-1;}};go(0);sort(ans.begin(),ans.end());return ans;}
bool pairfree(const G&a){for(int i=0;i<(int)a.size();i++)for(int j=0;j<i;j++){bool mod=true;for(int k=0;k<(int)a.size();k++)if(k!=i&&k!=j&&arc(a,k,i)!=arc(a,k,j))mod=false;if(mod)return false;}return true;}
G relabel(const G&a,const P&p){G b(a.size());for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)a.size();j++)if(arc(a,p[i],p[j]))b[i]|=1u<<j;return b;}
G canon(const G&a){P p(a.size());iota(p.begin(),p.end(),0);G best=a;do{best=min(best,relabel(a,p));}while(next_permutation(p.begin(),p.end()));return best;}
G blow(const G&q,const P&w){P owner;for(int i=0;i<(int)w.size();i++)for(int j=0;j<w[i];j++)owner.push_back(i);G t(owner.size());for(int i=0;i<(int)t.size();i++)for(int j=i+1;j<(int)t.size();j++){bool forward=owner[i]==owner[j]||arc(q,owner[i],owner[j]);t[forward?i:j]|=1u<<(forward?j:i);}return t;}
P lift(const P&p,const P&w,bool anti){P start(w.size()+1);partial_sum(w.begin(),w.end(),start.begin()+1);P ans(start.back());for(int i=0;i<(int)w.size();i++)for(int j=0;j<w[i];j++)ans[start[i]+j]=start[p[i]]+(anti?w[i]-1-j:j);return ans;}
bool fixed(const P&p,const P&w){for(int i=0;i<(int)w.size();i++)if(w[i]!=w[p[i]])return false;return true;}
P cycle_type(const P&p){P seen(p.size()),c;for(int i=0;i<(int)p.size();i++)if(!seen[i]){int j=i,len=0;do{seen[j]=1;len++;j=p[j];}while(j!=i);c.push_back(len);}sort(c.begin(),c.end());return c;}
vector<ll> fixed_counts(const P&p,int limit){vector<ll>f(limit+1);f[p.size()]=1;for(int c:cycle_type(p))for(int n=c;n<=limit;n++)f[n]+=f[n-c];return f;}
P orbit_key(const P&w,const vector<P>&group){P key=w;for(auto&p:group){P z;for(int i:p)z.push_back(w[i]);key=min(key,z);}return key;}
vector<unsigned> blocks(const G&a){vector<unsigned>all,b;for(unsigned S=1;S<(1u<<a.size());S++){bool yes=true;for(int v=0;v<(int)a.size();v++)if(!(S>>v&1)&&(a[v]&S)&&(a[v]&S)!=S){yes=false;break;}if(!yes)continue;P deg;for(int v=0;v<(int)a.size();v++)if(S>>v&1)deg.push_back(pop(a[v]&S));sort(deg.begin(),deg.end());for(int i=0;i<(int)deg.size();i++)if(deg[i]!=i)yes=false;if(yes)all.push_back(S);}for(unsigned S:all){bool max=true;for(unsigned T:all)if(S!=T&&(S&T)==S){max=false;break;}if(max)b.push_back(S);}sort(b.begin(),b.end());return b;}
int main(){set<G>bank;bank.insert(G{0});for(int n=3;n<=5;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G a(n);int bit=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,bit++){bool f=code>>bit&1;a[f?i:j]|=1u<<(f?j:i);}if(pairfree(a))bank.insert(canon(a));}G ribbon(6);for(int i=0;i<6;i++)for(int j=i+1;j<6;j++){bool f=j!=i+1;ribbon[f?i:j]|=1u<<(f?j:i);}need(pairfree(ribbon),"ribbon canonical quotient");bank.insert(ribbon);G paley(7);for(int i=0;i<7;i++)for(int j:{1,2,4})paley[i]|=1u<<((i+j)%7);bank.insert(paley);
ll physical=0,mapchecks=0,blockchecks=0,orbitchecks=0,affinechecks=0,completionchecks=0;int seeds=0;for(auto&q:bank){int k=q.size();auto aut=maps(q,false),anti=maps(q,true);need(aut.size()%2==1,"odd automorphism group");need(anti.empty()||anti.size()==aut.size(),"anti coset");map<P,int>auttypes,antitypes;int involutions=0;for(auto&p:aut)auttypes[cycle_type(p)]++;for(auto&p:anti){auto c=cycle_type(p);antitypes[c]++;bool inv=true;for(int i=0;i<k;i++)if(p[p[i]]!=i)inv=false;involutions+=inv;if(k>1){need(count(c.begin(),c.end(),1)<=1,"at most one anti fixed vertex");for(int x:c)need(x==1||x%4==2,"anti cycle lengths");need((int)c.size()<=(k+1)/2,"anti dimension");need(((int)c.size()==(k+1)/2)==inv,"leading anti strata");}}
if(!anti.empty())need(involutions>0&&aut.size()%involutions==0,"involution existence and conjugacy count");vector<ll>u(101),s(101);for(auto&p:aut){auto f=fixed_counts(p,100);for(int n=0;n<=100;n++)u[n]+=f[n];}for(auto&p:anti){auto f=fixed_counts(p,100);for(int n=0;n<=100;n++)s[n]+=f[n];}for(int n=0;n<=100;n++){need(u[n]%(ll)aut.size()==0&&s[n]%(ll)aut.size()==0,"integral cycle index");u[n]/=aut.size();s[n]/=aut.size();if(k%2==0)need(n%2==0||s[n]==0,"even quotient odd total impossible");}
for(int n=k;n<=11;n++){set<P>orbits,symmetric;P w(k,1);function<void(int,int)>go=[&](int at,int remaining){if(at==k-1){if(remaining<1)return;w[at]=remaining;G a=blow(q,w);auto ga=maps(a,false),ha=maps(a,true);vector<P>predg,predh;for(auto&p:aut)if(fixed(p,w))predg.push_back(lift(p,w,false));for(auto&p:anti)if(fixed(p,w))predh.push_back(lift(p,w,true));sort(predg.begin(),predg.end());sort(predh.begin(),predh.end());need(ga==predg&&ha==predh,"all actual maps equal quotient lifts");mapchecks+=2;auto key=orbit_key(w,aut);orbits.insert(key);if(!ha.empty())symmetric.insert(key);if(n<=9){vector<unsigned>expected;int pos=0;for(int z:w){expected.push_back(((1u<<z)-1)<<pos);pos+=z;}sort(expected.begin(),expected.end());need(blocks(a)==expected,"actual maximal transitive blocks");blockchecks++;}if(k>=3&&n<=9){P initial=w;for(int i=0;i<2;i++)for(int j=i;j<2;j++)for(int x=1;x<=3;x++)for(int y=1;y<=3;y++){P v=initial;v[i]+=x-1;v[j]+=y-1;bool lhs=false;for(auto&p:anti)lhs|=fixed(p,v);G b=blow(q,v);need(lhs==!maps(b,true).empty(),"simultaneous affine clone test");affinechecks++;}}physical++;return;}for(int v=1;v<=remaining-(k-at-1);v++){w[at]=v;go(at+1,remaining-v);}};go(0,n);need((ll)orbits.size()==u[n]&&(ll)symmetric.size()==s[n],"orbit and trace count");orbitchecks++;}
// Exhaustive independent finite weight-box optimizer, including every set of mutable blocks.
vector<P> small;P weight(k,1);function<void(int)> smallgo=[&](int i){if(i==k){small.push_back(weight);return;}for(int v=1;v<=3;v++){weight[i]=v;smallgo(i+1);}};smallgo(0);vector<P> symmetric_small;for(auto&v:small){bool yes=false;for(auto&p:anti)yes|=fixed(p,v);if(yes)symmetric_small.push_back(v);}vector<P> invol;for(auto&p:anti){bool yes=true;for(int i=0;i<k;i++)yes&=p[p[i]]==i;if(yes)invol.push_back(p);}const int INF=1000000;
for(auto&w:small){vector<int>cost(1<<k,INF);for(auto&v:symmetric_small){int mask=0,c=0;bool yes=true;for(int i=0;i<k;i++){if(v[i]<w[i])yes=false;if(v[i]>w[i])mask|=1<<i;c+=v[i]-w[i];}if(yes)cost[mask]=min(cost[mask],c);}for(int b=0;b<k;b++)for(int mask=0;mask<(1<<k);mask++)if(mask>>b&1)cost[mask]=min(cost[mask],cost[mask^(1<<b)]);for(int mask=0;mask<(1<<k);mask++){int predicted=INF;for(auto&p:invol){bool yes=true;int c=0;for(int i=0;i<k;i++)if(i<p[i]){int j=p[i],m=max(w[i],w[j]);if((!(mask>>i&1)&&w[i]!=m)||(!(mask>>j&1)&&w[j]!=m))yes=false;c+=2*m-w[i]-w[j];}if(yes)predicted=min(predicted,c);}need(cost[mask]==predicted,"minimum permitted-cloning completion");completionchecks++;}}
cout<<"QUOTIENT "<<seeds++<<" rows";for(auto v:q)cout<<" "<<v;cout<<" aut "<<aut.size()<<" anti "<<anti.size()<<" anti_involutions "<<involutions<<" ordinary_7_11";for(int n=7;n<=11;n++)cout<<" "<<u[n];cout<<" self_converse_7_11";for(int n=7;n<=11;n++)cout<<" "<<s[n];cout<<"\n";
if(q==paley){need(auttypes==map<P,int>{{P(7,1),1},{P{7},6},{P{1,3,3},14}},"Paley automorphism cycle index");need(antitypes==map<P,int>{{P{1,2,2,2},7},{P{1,6},14}},"Paley anti cycle index");} }
cout<<"PASS quotient_seeds "<<seeds<<" physical_blowups "<<physical<<" full_map_comparisons "<<mapchecks<<" maximal_block_controls "<<blockchecks<<" orbit_order_controls "<<orbitchecks<<" affine_clone_controls "<<affinechecks<<" minimum_completion_controls "<<completionchecks<<" coefficient_limit 100\n";
}
